@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ChatbotScreen(
    messages: List<ChatMessageEntity>,
    latestDetection: DetectionHistoryEntity?,
    uiState: ChatbotUiState,
    onSendMessage: (String) -> Unit,
    onClearChat: () -> Unit,
    onClearError: () -> Unit,
    onBack: (() -> Unit)? = null,
    modifier: Modifier = Modifier
) {
    val listState = rememberLazyListState()
    var inputText by remember { mutableStateOf("") }

    LaunchedEffect(messages.size, uiState.isSending) {
        val totalItems = messages.size + if (uiState.isSending) 1 else 0
        if (totalItems > 0) {
            listState.animateScrollToItem(totalItems - 1)
        }
    }

    Scaffold(
        modifier = modifier.imePadding(),
        containerColor = ChatBackgroundLight,
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            text = "Dokter Gigi Virtual",
                            color = ChatTextPrimary,
                            fontSize = 17.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                        Text(
                            text = "OralHealth+ AI Kontekstual",
                            color = ChatTextMuted,
                            fontSize = 12.sp
                        )
                    }
                },
                navigationIcon = {
                    if (onBack != null) {
                        IconButton(onClick = onBack) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                                contentDescription = "Kembali",
                                tint = ChatTextPrimary
                            )
                        }
                    }
                },
                actions = {
                    if (messages.isNotEmpty()) {
                        IconButton(onClick = onClearChat) {
                            Icon(
                                imageVector = Icons.Filled.DeleteOutline,
                                contentDescription = "Bersihkan riwayat chat",
                                tint = ChatTextMuted
                            )
                        }
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.White)
            )
        },
        bottomBar = {
            Surface(
                color = Color.White,
                shadowElevation = 2.dp
            ) {
                Column(modifier = Modifier.navigationBarsPadding()) {
                    HorizontalDivider(color = ChatBorderHairline)
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 10.dp),
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        OutlinedTextField(
                            value = inputText,
                            onValueChange = { inputText = it.take(1000) },
                            placeholder = { Text("Tanyakan keluhan atau perawatan gigi...", fontSize = 14.sp) },
                            maxLines = 3,
                            shape = RoundedCornerShape(14.dp),
                            modifier = Modifier.weight(1f)
                        )
                        Spacer(modifier = Modifier.width(8.dp))
                        IconButton(
                            onClick = {
                                val text = inputText.trim()
                                if (text.isNotEmpty() && !uiState.isSending) {
                                    onSendMessage(text)
                                    inputText = ""
                                }
                            },
                            enabled = inputText.isNotBlank() && !uiState.isSending,
                            modifier = Modifier
                                .size(48.dp)
                                .clip(CircleShape)
                                .background(
                                    if (inputText.isNotBlank() && !uiState.isSending) {
                                        ChatPrimaryBlue
                                    } else {
                                        ChatBorderHairline
                                    }
                                )
                        ) {
                            Icon(
                                imageVector = Icons.AutoMirrored.Filled.Send,
                                contentDescription = "Kirim pesan",
                                tint = Color.White,
                                modifier = Modifier.size(20.dp)
                            )
                        }
                    }
                }
            }
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            DetectionContextBanner(latestDetection = latestDetection)

            if (uiState.quickPrompts.isNotEmpty()) {
                LazyRow(
                    contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    items(uiState.quickPrompts) { prompt ->
                        SuggestionChip(
                            onClick = { if (!uiState.isSending) onSendMessage(prompt) },
                            label = { Text(prompt, fontSize = 12.sp, color = ChatTextPrimary) },
                            colors = SuggestionChipDefaults.suggestionChipColors(containerColor = Color.White),
                            border = BorderStroke(1.dp, ChatBorderHairline)
                        )
                    }
                }
            }

            if (uiState.errorMessage != null) {
                ChatErrorBanner(message = uiState.errorMessage, onDismiss = onClearError)
            }

            LazyColumn(
                state = listState,
                modifier = Modifier
                    .weight(1f)
                    .fillMaxWidth(),
                contentPadding = PaddingValues(horizontal = 16.dp, vertical = 12.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp)
            ) {
                if (messages.isEmpty()) {
                    item {
                        WelcomeVirtualDentistCard(latestDetection = latestDetection)
                    }
                } else {
                    items(messages, key = { it.id }) { msg ->
                        if (msg.isFromUser) {
                            UserChatBubble(text = msg.message)
                        } else {
                            VirtualDentistBubble(text = msg.message)
                        }
                    }
                }

                if (uiState.isSending) {
                    item {
                        TypingStatusBubble()
                    }
                }
            }
        }
    }
}

@Composable
private fun DetectionContextBanner(latestDetection: DetectionHistoryEntity?) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp),
        shape = RoundedCornerShape(12.dp),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        border = BorderStroke(1.dp, ChatBorderHairline)
    ) {
        if (latestDetection != null) {
            val confidenceStr = String.format(Locale.US, "%.1f%%", latestDetection.confidence * 100f)
            val (urgLabel, urgBg, urgFg) = when (latestDetection.urgensi.uppercase()) {
                "EDUKASI_MANDIRI" -> Triple("Edukasi Mandiri", Color(0xFFE8F5E9), Color(0xFF1E6B34))
                "KONTROL_RUTIN" -> Triple("Kontrol Rutin", Color(0xFFFFF0CC), Color(0xFF6B4200))
                "SEGERA_KE_DOKTER" -> Triple("Segera ke Dokter", Color(0xFFFFEBEE), Color(0xFF9B1C1C))
                else -> Triple(latestDetection.urgensi, Color(0xFFE2E8F0), ChatTextPrimary)
            }
            Column(modifier = Modifier.padding(12.dp)) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = "Konteks Deteksi Terakhir",
                            color = ChatTextMuted,
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = "${latestDetection.kelas.replace("_", " ")} ($confidenceStr)",
                            color = ChatTextPrimary,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    Box(
                        modifier = Modifier
                            .background(urgBg, RoundedCornerShape(8.dp))
                            .padding(horizontal = 8.dp, vertical = 4.dp)
                    ) {
                        Text(text = urgLabel, color = urgFg, fontSize = 11.sp, fontWeight = FontWeight.SemiBold)
                    }
                }
                if (latestDetection.catatanKeluhan.isNotBlank()) {
                    Spacer(modifier = Modifier.height(6.dp))
                    Text(
                        text = "Keluhan: ${latestDetection.catatanKeluhan}",
                        color = ChatTextMuted,
                        fontSize = 12.sp
                    )
                }
            }
        } else {
            Row(
                modifier = Modifier.padding(12.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.Filled.MedicalServices,
                    contentDescription = null,
                    tint = ChatPrimaryBlue,
                    modifier = Modifier.size(20.dp)
                )
                Spacer(modifier = Modifier.width(10.dp))
                Column {
                    Text(
                        text = "Mode Konsultasi Umum",
                        color = ChatTextPrimary,
                        fontSize = 14.sp,
                        fontWeight = FontWeight.SemiBold
                    )
                    Text(
                        text = "Belum ada riwayat deteksi foto mulut tersimpan.",
                        color = ChatTextMuted,
                        fontSize = 12.sp
                    )
                }
            }
        }
    }
}

